    def __init__(self, items=()):
        # items: iterable of (var, value) pairs, value is int or TOP.
        self._map = dict(items)

    @property
    def values(self) -> dict:
        return dict(self._map)

    def get(self, var: str):
        return self._map.get(var, TOP)

    def assign(self, var: str, value) -> "ExplicitValueState":
        new_map = dict(self._map)
        new_map[var] = value
        return ExplicitValueState(new_map.items())

    def concrete_env(self) -> dict:
        """Environment with only the concretely known (int) values."""
        return {v: val for v, val in self._map.items() if isinstance(val, int)}

    def is_less_or_equal(self, other: "ExplicitValueState") -> bool:
        """self ⊑ other iff wherever other is concrete, self has the same value."""
        for var, val in other._map.items():
            if isinstance(val, int) and self._map.get(var, TOP) != val:
                return False
        return True

    def __eq__(self, other) -> bool:
        return isinstance(other, ExplicitValueState) and self._map == other._map

    def __hash__(self) -> int:
        return hash(("val", frozenset(self._map.items())))

    def __repr__(self) -> str:
        inner = ", ".join(f"{v}={val}" for v, val in sorted(self._map.items()))
        return f"{{{inner}}}"


class ExplicitValueDomain(AbstractDomain):
    def is_less_or_equal(self, state1, state2) -> bool:
        return state1.is_less_or_equal(state2)

    def join(self, state1, state2):
        merged = {}
        for var in set(state1.values) | set(state2.values):
            v1, v2 = state1.get(var), state2.get(var)
            merged[var] = v1 if v1 == v2 else TOP
        return ExplicitValueState(merged.items())

    def get_top(self):
        return ExplicitValueState()

    def get_bottom(self):
        return ExplicitValueState()


class ExplicitValueTransferRelation(TransferRelation):
    """Concrete evaluation of assignments and feasibility of assume edges."""

    def get_abstract_successors(self, state: ExplicitValueState, precision,
                                edge: CFAEdge):
        if edge.edge_type == EdgeType.ASSIGNMENT:
            env = state.concrete_env()
            value = evaluate_expression(edge.expression, env)
            if value is None:
                value = TOP
            return [state.assign(edge.variable, value)]

        if edge.edge_type in (EdgeType.ASSUME_TRUE, EdgeType.ASSUME_FALSE):
            env = state.concrete_env()
            result = evaluate_condition(edge.expression, env)
            if result is None:
                # Unknown (TOP involved): both branches are feasible.
                return [state]
            if edge.edge_type == EdgeType.ASSUME_TRUE:
                return [state] if result else []
            else:
                return [state] if not result else []

        # BLANK, ASSERT, FUNCTION_CALL: no effect on values.
        return [state]


class ExplicitValueStopOperator(StopOperator):
    """Covered iff some reached state has the same or less-precise values."""

    def stop(self, state, reached, precision) -> bool:
        return any(state.is_less_or_equal(r) for r in reached)


class ExplicitValueCPA(ConfigurableProgramAnalysis):
    def __init__(self):
        self._domain = ExplicitValueDomain()
        self._transfer = ExplicitValueTransferRelation()
        self._merge = SepMergeOperator()
        self._stop = ExplicitValueStopOperator()

    def get_abstract_domain(self):
        return self._domain

    def get_transfer_relation(self):
        return self._transfer

    def get_merge_operator(self):
        return self._merge

    def get_stop_operator(self):
        return self._stop

    def get_initial_state(self, node_id: int):
        return ExplicitValueState()

    def get_initial_precision(self):
        return None


# ---------------------------------------------------------------------------
# CompositeCPA
# ---------------------------------------------------------------------------

class CompositeState(AbstractState):
    """Product state: a tuple of component states (first is the location)."""

    def __init__(self, components: tuple):
        self.components = tuple(components)

    @property
    def location(self) -> int:
        return self.components[0].node_id

    def __eq__(self, other) -> bool:
        return isinstance(other, CompositeState) and self.components == other.components

    def __hash__(self) -> int:
        return hash(self.components)

    def __repr__(self) -> str:
        return "(" + ", ".join(repr(c) for c in self.components) + ")"


class CompositeDomain(AbstractDomain):
    def __init__(self, domains):
        self.domains = domains

    def is_less_or_equal(self, state1, state2) -> bool:
        return all(
            d.is_less_or_equal(s1, s2)
            for d, s1, s2 in zip(self.domains, state1.components, state2.components)
        )

    def join(self, state1, state2):
        return CompositeState(tuple(
            d.join(s1, s2)
            for d, s1, s2 in zip(self.domains, state1.components, state2.components)
        ))

    def get_top(self):
        return CompositeState(tuple(d.get_top() for d in self.domains))

    def get_bottom(self):
        return CompositeState(tuple(d.get_bottom() for d in self.domains))


class CompositeTransferRelation(TransferRelation):
    def __init__(self, transfers):
        self.transfers = transfers

    def get_abstract_successors(self, state: CompositeState, precision,
                                edge: CFAEdge):
        # Compute component-wise successors and take their cartesian product.
        component_successors = [
            t.get_abstract_successors(s, precision, edge)
            for t, s in zip(self.transfers, state.components)
        ]
        if any(len(succs) == 0 for succs in component_successors):
            return []
        result = [CompositeState(())]
        for succs in component_successors:
            result = [
                CompositeState(base.components + (s,))
                for base in result
                for s in succs
            ]
        return result


class CompositeMergeOperator(MergeOperator):
    def __init__(self, merges):
        self.merges = merges

    def merge(self, state1, state2, precision):
        return CompositeState(tuple(
            m.merge(s1, s2, precision)
            for m, s1, s2 in zip(self.merges, state1.components, state2.components)
        ))


class CompositeStopOperator(StopOperator):
    """Covered iff some reached state covers every component state."""

    def __init__(self, stops):
        self.stops = stops

    def stop(self, state, reached, precision) -> bool:
        for r in reached:
            if all(
                stop.stop(s, [rs], precision)
                for stop, s, rs in zip(self.stops, state.components, r.components)
            ):
                return True
        return False


class CompositeCPA(ConfigurableProgramAnalysis):
    """Product CPA combining several component CPAs."""

    def __init__(self, cpas: list):
        self.cpas = list(cpas)
        self._domain = CompositeDomain([c.get_abstract_domain() for c in self.cpas])
        self._transfer = CompositeTransferRelation(
            [c.get_transfer_relation() for c in self.cpas])
        self._merge = CompositeMergeOperator(
            [c.get_merge_operator() for c in self.cpas])
        self._stop = CompositeStopOperator(
            [c.get_stop_operator() for c in self.cpas])

    def get_abstract_domain(self):
        return self._domain

    def get_transfer_relation(self):
        return self._transfer

    def get_merge_operator(self):
        return self._merge

    def get_stop_operator(self):
        return self._stop

    def get_initial_state(self, node_id: int):
        return CompositeState(tuple(
            c.get_initial_state(node_id) for c in self.cpas))

    def get_initial_precision(self):
        return None


# ---------------------------------------------------------------------------
# CPA worklist algorithm
# ---------------------------------------------------------------------------

def run_cpa_algorithm(cpa: ConfigurableProgramAnalysis, cfa: CFA,
                      timelimit: float = 900.0):
    """Generic CPA reachability algorithm.

    Maintains a worklist (frontier) and a reached set. Pops states, computes
    successors via the transfer relation, applies merge with reached states at
    the same location, and applies stop for coverage. Reports FALSE as soon as
    an error location is reached, TRUE when the worklist is exhausted.

    Returns (verdict, statistics, error_path).
    """
    start = time.time()
    precision = cpa.get_initial_precision()
    transfer = cpa.get_transfer_relation()
    merge_op = cpa.get_merge_operator()
    stop_op = cpa.get_stop_operator()

    initial = cpa.get_initial_state(cfa.entry_node)
    reached = [initial]
    worklist = [initial]
    parent = {initial: None}
    via_edge = {}

    iterations = 0
    while worklist:
        if time.time() - start > timelimit:
            return Verdict.UNKNOWN, {
                "reached_states": len(reached),
                "iterations": iterations,
                "reason": "timeout",
            }, []

        state = worklist.pop()
        iterations += 1
        loc = state.location

        for edge in cfa.get_successors(loc):
            for succ in transfer.get_abstract_successors(state, precision, edge):
                succ_loc = succ.location

                if cfa.nodes[succ_loc].is_error:
                    parent[succ] = state
                    via_edge[succ] = edge
                    path = _reconstruct_path(succ, parent, via_edge)
                    return Verdict.FALSE, {
                        "reached_states": len(reached),
                        "iterations": iterations,
                        "error_path_length": len(path),
                    }, path

                # Merge with reached states at the same location.
                merged_existing = False
                for i, r in enumerate(reached):
                    if r.location != succ_loc:
                        continue
                    merged = merge_op.merge(succ, r, precision)
                    if merged != r:
                        reached[i] = merged
                        if merged not in parent:
                            parent[merged] = state
                            via_edge[merged] = edge
                        if merged not in worklist:
                            worklist.append(merged)
                        merged_existing = True
                if merged_existing:
                    continue

                # Stop: skip if already covered by the reached set.
                same_loc = [r for r in reached if r.location == succ_loc]
                if stop_op.stop(succ, same_loc, precision):
                    continue

                parent[succ] = state
                via_edge[succ] = edge
                reached.append(succ)
                worklist.append(succ)

    return Verdict.TRUE, {
        "reached_states": len(reached),
        "iterations": iterations,
    }, []


def _reconstruct_path(state, parent, via_edge) -> list:
    """Reconstruct the error path (list of step descriptions)."""
    chain = []
    s = state
    while s is not None:
        chain.append(s)
        s = parent.get(s)
    chain.reverse()

    path = []
    for i, s in enumerate(chain):
        step = {
            "step": i,
            "location": s.location,
            "state": repr(s),
        }
        if s in via_edge:
            e = via_edge[s]
            step["edge"] = f"{e.source} -> {e.target}: {e.edge_type.value} {e.expression}"
        path.append(step)
    return path


# ---------------------------------------------------------------------------
# Entry point
# ---------------------------------------------------------------------------

def run_value_analysis(cfa: CFA, timelimit: float = 900.0) -> VerificationResult:
    """Run explicit value analysis on the given CFA."""
    cpa = CompositeCPA([LocationCPA(), ExplicitValueCPA()])
    verdict, stats, error_path = run_cpa_algorithm(cpa, cfa, timelimit)

    result = VerificationResult(verdict=verdict, statistics=stats)
    if verdict == Verdict.FALSE:
        result.property_violated = "assertion"
        result.error_path = error_path
        result.statistics["counterexample"] = _format_path(error_path)
    return result


def _format_path(path: list) -> str:
    parts = []
    for step in path:
        desc = f"L{step['location']}"
        if "edge" in step:
            desc += f" [{step['edge']}]"
        parts.append(desc)
    return " -> ".join(parts)

args.content:
"""Predicate analysis with path feasibility checking (cpachecker_v1).

Implements:
- A small expression/condition parser producing ASTs from CFA edge strings.
- PathFeasibilityChecker: a lightweight linear-arithmetic constraint solver
  (Fourier-Motzkin elimination over rationals + equality substitution +
  parity reasoning for `% 2` constraints).
- PredicateAbstractState: a set of symbolic linear constraints (predicates)
  over program variables.
- PredicateTransferRelation: strongest-postcondition style transfer
  (variable projection via Gaussian/Fourier-Motzkin elimination) with
  path feasibility pruning on assume edges.
- PredicateCPA with 'sep' merge and logical-implication stop.
- run_predicate_analysis(cfa, timelimit): entry point.
"""

from __future__ import annotations

import time
from fractions import Fraction
from typing import Optional

from cpachecker.cfa import CFA, CFAEdge, EdgeType
from cpachecker.cpa_interface import (
    AbstractDomain,
    AbstractState,
    ConfigurableProgramAnalysis,
    MergeOperator,
    Precision,
    StopOperator,
    TransferRelation,
)
from cpachecker.expression import is_nondeterministic
from cpachecker.parser import tokenize
from cpachecker.result import Verdict, VerificationResult
from cpachecker.analyses.value_analysis import (
    CompositeCPA,
    LocationCPA,
    SepMergeOperator,
    run_cpa_algorithm,
)


# ---------------------------------------------------------------------------
# Expression parsing (C expression strings -> AST tuples)
# ---------------------------------------------------------------------------
# AST forms:
#   ("num", int) | ("var", name) | ("call", name)
#   ("unop", op, expr) | ("binop", op, left, right)

def parse_expr(text: str):
    """Parse a C expression string into an AST tuple."""
    tokens = [t for t in tokenize(text)]
    parser = _ExprParser(tokens)
    ast = parser.parse_or()
    return ast


class _ExprParser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def advance(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def parse_or(self):
        left = self.parse_and()
        while self.peek() and self.peek().value == "||":
            self.advance()
            left = ("binop", "||", left, self.parse_and())
        return left

    def parse_and(self):
        left = self.parse_equality()
        while self.peek() and self.peek().value == "&&":
            self.advance()
            left = ("binop", "&&", left, self.parse_equality())
        return left

    def parse_equality(self):
        left = self.parse_relational()
        while self.peek() and self.peek().value in ("==", "!="):
            op = self.advance().value
            left = ("binop", op, left, self.parse_relational())
        return left

    def parse_relational(self):
        left = self.parse_additive()
        while self.peek() and self.peek().value in ("<", "<=", ">", ">="):
            op = self.advance().value
            left = ("binop", op, left, self.parse_additive())
        return left

    def parse_additive(self):
        left = self.parse_multiplicative()
        while self.peek() and self.peek().value in ("+", "-"):
            op = self.advance().value
            left = ("binop", op, left, self.parse_multiplicative())
        return left

    def parse_multiplicative(self):
        left = self.parse_unary()
        while self.peek() and self.peek().value in ("*", "/", "%"):
            op = self.advance().value
            left = ("binop", op, left, self.parse_unary())
        return left

    def parse_unary(self):
        tok = self.peek()
        if tok and tok.value in ("!", "-", "+"):
            op = self.advance().value
            return ("unop", op, self.parse_unary())
        return self.parse_primary()

    def parse_primary(self):
        tok = self.advance()
        if tok.kind == "NUMBER":
            return ("num", int(tok.value.rstrip("UuLl") or "0"))
        if tok.kind == "IDENT":
            if self.peek() and self.peek().kind == "LPAREN":
                # function call: skip balanced parens
                self.advance()
                depth = 1
                while self.pos < len(self.tokens) and depth > 0:
                    t = self.advance()
                    if t.kind == "LPAREN":
                        depth += 1
                    elif t.kind == "RPAREN":
                        depth -= 1
                return ("call", tok.value)
            return ("var", tok.value)
        if tok.kind == "LPAREN":
            ast = self.parse_or()
            if self.peek() and self.peek().kind == "RPAREN":
                self.advance()
            return ast
        raise SyntaxError(f"Unexpected token {tok} in expression")


def substitute(ast, store: dict):
    """Substitute ("var", v) nodes according to store {name: AST}."""
    kind = ast[0]
    if kind == "var":
        return store.get(ast[1], ("var", ast[1]))
    if kind == "binop":
        return ("binop", ast[1], substitute(ast[2], store), substitute(ast[3], store))
    if kind == "unop":
        return ("unop", ast[1], substitute(ast[2], store))
    return ast


# ---------------------------------------------------------------------------
# Linear forms and constraints
# ---------------------------------------------------------------------------
# Linear form: (coeffs: dict var -> Fraction, const: Fraction) meaning
#   sum(coeffs[v] * v) + const
#
# Constraint forms (hashable tuples):
#   ("le",  coeffs_tuple, rhs)            sum(coeffs*v) <= rhs
#   ("eq",  coeffs_tuple, rhs)            sum(coeffs*v) == rhs
#   ("mod", coeffs_tuple, const, m, r)    (sum(coeffs*v) + const) % m == r
# where coeffs_tuple is a tuple of sorted (var, Fraction) pairs.

def _lin_num(v: int):
    return ({}, Fraction(v))


def _lin_add(a, b):
    coeffs = dict(a[0])
    for v, c in b[0].items():
        coeffs[v] = coeffs.get(v, Fraction(0)) + c
        if coeffs[v] == 0:
            del coeffs[v]
    return (coeffs, a[1] + b[1])


def _lin_neg(a):
    return ({v: -c for v, c in a[0].items()}, -a[1])


def _lin_scale(a, factor: Fraction):
    return ({v: c * factor for v, c in a[0].items()}, a[1] * factor)


def to_linear(ast):
    """Convert an AST to a linear form (coeffs, const), or None if nonlinear."""
    kind = ast[0]
    if kind == "num":
        return _lin_num(ast[1])
    if kind == "var":
        return ({ast[1]: Fraction(1)}, Fraction(0))
    if kind == "unop":
        if ast[1] == "-":
            inner = to_linear(ast[2])
            return _lin_neg(inner) if inner else None
        if ast[1] == "+":
            return to_linear(ast[2])
        return None
    if kind == "binop":
        op = ast[1]
        left = to_linear(ast[2])
        right = to_linear(ast[3])
        if op == "+" and left and right:
            return _lin_add(left, right)
        if op == "-" and left and right:
            return _lin_add(left, _lin_neg(right))
        if op == "*":
            if left and not left[0]:
                return _lin_scale(right, left[1]) if right else None
            if right and not right[0]:
                return _lin_scale(left, right[1]) if left else None
            return None
        if op == "/" and left and right and not right[0] and right[1] != 0:
            return _lin_scale(left, Fraction(1, 1) / right[1])
        return None
    return None


def _coeffs_tuple(coeffs: dict) -> tuple:
    return tuple(sorted((v, c) for v, c in coeffs.items() if c != 0))


def _make_le(coeffs: dict, const: Fraction, rhs: Fraction):
    """Constraint: sum(coeffs*v) + const <= rhs  ==>  sum(coeffs*v) <= rhs-const."""
    return ("le", _coeffs_tuple(coeffs), rhs - const)


def _make_eq(coeffs: dict, const: Fraction, rhs: Fraction):
    return ("eq", _coeffs_tuple(coeffs), rhs - const)


def _extract_mod(ast):
    """If ast is `e % m` with e linear and m a positive constant, return
    (coeffs, const, m); else None."""
    if ast[0] == "binop" and ast[1] == "%" and ast[3][0] == "num":
        m = ast[3][1]
        if m > 0:
            lin = to_linear(ast[2])
            if lin is not None:
                return (lin[0], lin[1], m)
    return None


def _atom_to_dnf(op: str, left_ast, right_ast):
    """Convert a comparison atom to a DNF (list of disjuncts = constraint lists)."""
    left_mod = _extract_mod(left_ast)
    right_mod = _extract_mod(right_ast)

    # Modular comparisons: reduce `expr % m <cmp> <const>` to residue disjuncts.
    if left_mod is not None and right_ast[0] == "num":
        coeffs, const, m = left_mod
        target = right_ast[1]
        residues = []
        for r in range(m):
            holds = {
                "==": r == target, "!=": r != target,
                "<": r < target, "<=": r <= target,
                ">": r > target, ">=": r >= target,
            }[op]
            if holds:
                residues.append(r)
        if not residues:
            return []  # unsatisfiable atom
        return [[("mod", _coeffs_tuple(coeffs), const, m, r)] for r in residues]

    left = to_linear(left_ast)
    right = to_linear(right_ast)
    if left is None or right is None:
        return [[]]  # cannot reason: treat as unconstrained (feasible)
    diff = _lin_add(left, _lin_neg(right))  # left - right
    coeffs, const = diff
    if op == "<":
        return [[_make_le(coeffs, const, Fraction(-1))]]
    if op == "<=":
        return [[_make_le(coeffs, const, Fraction(0))]]
    if op == ">":
        return [[_make_le(_lin_neg(diff)[0], _lin_neg(diff)[1], Fraction(-1))]]
    if op == ">=":
        return [[_make_le(_lin_neg(diff)[0], _lin_neg(diff)[1], Fraction(0))]]
    if op == "==":
        return [[_make_eq(coeffs, const, Fraction(0))]]
    if op == "!=":
        le = _make_le(coeffs, const, Fraction(-1))
        ge = _make_le(_lin_neg(diff)[0], _lin_neg(diff)[1], Fraction(-1))
        return [[le], [ge]]
    return [[]]


def cond_to_dnf(ast, negate: bool = False):
    """Convert a condition AST to DNF: a list of disjuncts, each a list of
    constraints. `negate` negates the whole condition."""
    kind = ast[0]
    if kind == "unop" and ast[1] == "!":
        return cond_to_dnf(ast[2], not negate)
    if kind == "binop" and ast[1] == "&&":
        a = cond_to_dnf(ast[2], negate)
        b = cond_to_dnf(ast[3], negate)
        if negate:  # !(a && b) == !a || !b
            return a + b
        return [da + db for da in a for db in b]
    if kind == "binop" and ast[1] == "||":
        a = cond_to_dnf(ast[2], negate)
        b = cond_to_dnf(ast[3], negate)
        if negate:  # !(a || b) == !a && !b
            return [da + db for da in a for db in b]
        return a + b
    if kind == "binop" and ast[1] in ("==", "!=", "<", "<=", ">", ">="):
        op = ast[1]
        if negate:
            op = {"==": "!=", "!=": "==", "<": ">=", "<=": ">",
                  ">": "<=", ">=": "<"}[op]
        return _atom_to_dnf(op, ast[2], ast[3])
    # Arbitrary expression used as a condition: truthiness == (e != 0).
    if negate:
        return _atom_to_dnf("==", ast, ("num", 0))
    return _atom_to_dnf("!=", ast, ("num", 0))


# ---------------------------------------------------------------------------
# PathFeasibilityChecker: linear constraint solving
# ---------------------------------------------------------------------------

def _substitute_var(cons, var, expr_coeffs, expr_const):
    """Replace `var` by (sum(expr_coeffs*v) + expr_const) in all constraints.

    cons: list of (coeffs_dict, rhs) meaning sum(coeffs*v) <= rhs (or ==).
    """
    out = []
    for coeffs, rhs in cons:
        if var not in coeffs:
            out.append((coeffs, rhs))
            continue
        a = coeffs[var]
        newc = dict(coeffs)
        del newc[var]
        for v, c in expr_coeffs.items():
            newc[v] = newc.get(v, Fraction(0)) + a * c
            if newc[v] == 0:
                del newc[v]
        out.append((newc, rhs - a * expr_const))
    return out


def fourier_motzkin_sat(eqs, les) -> bool:
    """Check satisfiability of linear constraints over rationals.

    eqs: list of (coeffs dict, rhs) equalities; les: same for <=.
    Uses equality substitution then Fourier-Motzkin elimination.
    """
    eqs = [(dict(c), Fraction(r)) for c, r in eqs]
    les = [(dict(c), Fraction(r)) for c, r in les]

    # Eliminate variables using equalities.
    while True:
        pivot = None
        for i, (coeffs, rhs) in enumerate(eqs):
            if not coeffs:
                if rhs != 0:
                    return False
            else:
                pivot = i
                break
        if pivot is None:
            break
        coeffs, rhs = eqs.pop(pivot)
        var = next(iter(coeffs))
        a = coeffs[var]
        # var = (rhs - sum_{u != var} c_u * u) / a
        expr_coeffs = {u: -c / a for u, c in coeffs.items() if u != var}
        expr_const = rhs / a
        eqs = _substitute_var(eqs, var, expr_coeffs, expr_const)
        les = _substitute_var(les, var, expr_coeffs, expr_const)

    # Check trivial inequalities, then FM-eliminate remaining variables.
    cons = []
    for coeffs, rhs in les:
        if not coeffs:
            if Fraction(0) > rhs:
                return False
        else:
            cons.append((coeffs, rhs))

    remaining = set()
    for coeffs, _ in cons:
        remaining.update(coeffs)

    for var in remaining:
        pos = [(c, b) for c, b in cons if c.get(var, 0) > 0]
        neg = [(c, b) for c, b in cons if c.get(var, 0) < 0]
        indep = [(c, b) for c, b in cons if c.get(var, 0) == 0]
        new_cons = list(indep)
        for c1, b1 in pos:
            a1 = c1[var]
            for c2, b2 in neg:
                a2 = -c2[var]
                combined = {}
                for u in set(c1) | set(c2):
                    if u == var:
                        continue
                    val = a2 * c1.get(u, Fraction(0)) + a1 * c2.get(u, Fraction(0))
                    if val != 0:
                        combined[u] = val
                newb = a2 * b1 + a1 * b2
                if not combined and Fraction(0) > newb:
                    return False
                if combined:
                    new_cons.append((combined, newb))
        cons = new_cons
    return True


def _concrete_values(eqs):
    """Extract concrete values for variables pinned by equalities."""
    values = {}
    for coeffs, rhs in eqs:
        if len(coeffs) == 1:
            (v, c), = coeffs.items()
            val = Fraction(rhs) / c
            values[v] = val
    return values


def _parity_of(coeffs, const, concrete, parity_facts):
    """Compute (expr) % 2 if determinable, else None."""
    if const.denominator != 1:
        return None
    p = int(const) % 2
    for v, c in coeffs.items():
        if c.denominator != 1:
            return None
        ci = int(c)
        if ci % 2 == 0:
            continue
        if v in concrete:
            if concrete[v].denominator != 1:
                return None
            p ^= int(concrete[v]) % 2
        elif v in parity_facts:
            p ^= parity_facts[v]
        else:
            return None
    return p


class PathFeasibilityChecker:
    """Maintains a set of linear arithmetic constraints and checks SAT/UNSAT
    via equality substitution, Fourier-Motzkin elimination and parity
    reasoning (for `% 2` constraints)."""

    def __init__(self, constraints=()):
        self.constraints = frozenset(constraints)

    def _split(self):
        eqs, les, mods = [], [], []
        for con in self.constraints:
            if con[0] == "eq":
                eqs.append((dict(con[1]), Fraction(con[2])))
            elif con[0] == "le":
                les.append((dict(con[1]), Fraction(con[2])))
            elif con[0] == "mod":
                mods.append(con)
        return eqs, les, mods

    def is_sat(self, extra=()) -> bool:
        """Return True iff the constraint set (plus `extra`) is satisfiable."""
        if extra:
            checker = PathFeasibilityChecker(self.constraints | frozenset(extra))
            return checker.is_sat()
        eqs, les, mods = self._split()
        if not fourier_motzkin_sat(eqs, les):
            return False
        # Parity reasoning for mod-2 constraints.
        concrete = _concrete_values(eqs)
        parity_facts = {}
        for con in mods:
            _, coeffs_t, const, m, r = con
            if m != 2:
                continue
            coeffs = dict(coeffs_t)
            if len(coeffs) == 1 and const == 0:
                (v, c), = coeffs.items()
                if c == 1:
                    if v in parity_facts and parity_facts[v] != r % 2:
                        return False
                    parity_facts[v] = r % 2
        for con in mods:
            _, coeffs_t, const, m, r = con
            if m != 2:
                continue
            p = _parity_of(dict(coeffs_t), Fraction(const), concrete, parity_facts)
            if p is not None and p != r % 2:
                return False
        return True

    def entails(self, constraint) -> bool:
        """Return True iff this constraint set logically implies `constraint`."""
        kind = constraint[0]
        if kind == "le":
            # not (sum <= rhs)  <=>  sum >= rhs+1  <=>  -sum <= -rhs-1 (integers)
            neg = ("le", _coeffs_tuple({v: -c for v, c in constraint[1]}),
                   -Fraction(constraint[2]) - 1)
            return not self.is_sat([neg])
        if kind == "eq":
            coeffs = dict(constraint[1])
            rhs = Fraction(constraint[2])
            return (self.entails(("le", constraint[1], rhs))
                    and self.entails(("le", _coeffs_tuple(
                        {v: -c for v, c in coeffs.items()}), -rhs)))
        if kind == "mod":
            _, coeffs_t, const, m, r = constraint
            if m != 2:
                return False
            eqs, _, mods = self._split()
            concrete = _concrete_values(eqs)
            parity_facts = {}
            for mc in mods:
                if mc[3] != 2:
                    continue
                mcoeffs = dict(mc[1])
                if len(mcoeffs) == 1 and mc[2] == 0:
                    (v, c), = mcoeffs.items()
                    if c == 1:
                        parity_facts[v] = mc[4] % 2
            p = _parity_of(dict(coeffs_t), Fraction(const), concrete, parity_facts)
            return p is not None and p == r % 2
        return False

    def __repr__(self):
        return " ∧ ".join(repr(c) for c in sorted(self.constraints, key=str)) or "true"


# ---------------------------------------------------------------------------
# Predicate abstract state and CPA
# ---------------------------------------------------------------------------

def eliminate_variable(eqs, les, var):
    """Project out `var` from (eqs, les) via Gaussian/Fourier-Motzkin
    elimination. Returns new (eqs, les) constraint lists."""
    eqs = [(dict(c), r) for c, r in eqs]
    les = [(dict(c), r) for c, r in les]

    with_var = [(c, b) for c, b in eqs if var in c]
    without_var = [(c, b) for c, b in eqs if var not in c]

    if with_var:
        coeffs, rhs = with_var[0]
        a = coeffs[var]
        expr_coeffs = {u: -c / a for u, c in coeffs.items() if u != var}
        expr_const = rhs / a
        eqs = _substitute_var(with_var[1:] + without_var, var, expr_coeffs, expr_const)
        les = _substitute_var(les, var, expr_coeffs, expr_const)
        return eqs, les

    # Fourier-Motzkin elimination for inequalities.
    pos = [(c, b) for c, b in les if c.get(var, 0) > 0]
    neg = [(c, b) for c, b in les if c.get(var, 0) < 0]
    indep = [(c, b) for c, b in les if c.get(var, 0) == 0]
    new_les = list(indep)
    for c1, b1 in pos:
        a1 = c1[var]
        for c2, b2 in neg:
            a2 = -c2[var]
            combined = {}
            for u in set(c1) | set(c2):
                if u == var:
                    continue
                val = a2 * c1.get(u, Fraction(0)) + a1 * c2.get(u, Fraction(0))
                if val != 0:
                    combined[u] = val
            new_les.append((combined, a2 * b1 + a1 * b2))
    return without_var, new_les


class PredicateAbstractState(AbstractState):
    """Abstract state: a set of symbolic predicates (linear constraints)
    over program variables."""

    def __init__(self, constraints=()):
        self.checker = PathFeasibilityChecker(constraints)

    @property
    def constraints(self):
        return self.checker.constraints

    def is_less_or_equal(self, other: "PredicateAbstractState") -> bool:
        """self ⊑ other iff self's constraints imply every constraint of other
        (i.e. self denotes a subset of other's concrete states)."""
        return all(self.checker.entails(c) for c in other.constraints)

    def with_constraints(self, extra) -> "PredicateAbstractState":
        return PredicateAbstractState(self.constraints | frozenset(extra))

    def __eq__(self, other) -> bool:
        return (isinstance(other, PredicateAbstractState)
                and self.constraints == other.constraints)

    def __hash__(self) -> int:
        return hash(("pred", self.constraints))

    def __repr__(self) -> str:
        return f"P[{self.checker}]"


class PredicateDomain(AbstractDomain):
    def is_less_or_equal(self, state1, state2) -> bool:
        return state1.is_less_or_equal(state2)

    def join(self, state1, state2):
        # Semantic join is expensive; merge is 'sep' so this is unused.
        return state2

    def get_top(self):
        return PredicateAbstractState()

    def get_bottom(self):
        return PredicateAbstractState()


class PredicateTransferRelation(TransferRelation):
    """Strongest-postcondition style transfer over linear constraints.

    - Assignments x := e: rename x to x_old, add x = e(x_old), then project
      out x_old (exact for linear e; havoc x for nonlinear/nondet e).
    - Assume edges: conjoin the (negated) condition, split disjunctions into
      separate successor states, prune UNSAT paths (path feasibility).
    """

    def get_abstract_successors(self, state: PredicateAbstractState, precision,
                                edge: CFAEdge):
        if edge.edge_type == EdgeType.ASSIGNMENT:
            return [self._transfer_assignment(state, edge)]

        if edge.edge_type in (EdgeType.ASSUME_TRUE, EdgeType.ASSUME_FALSE):
            negate = edge.edge_type == EdgeType.ASSUME_FALSE
            ast = parse_expr(edge.expression)
            dnf = cond_to_dnf(ast, negate=negate)
            successors = []
            for disjunct in dnf:
                succ = state.with_constraints(disjunct)
                if succ.checker.is_sat():
                    successors.append(succ)
            return successors

        # BLANK, ASSERT, FUNCTION_CALL: predicates unchanged.
        return [state]

    def _transfer_assignment(self, state, edge):
        var = edge.variable
        if not var:
            return state

        lin = None
        if not is_nondeterministic(edge.expression):
            lin = to_linear(parse_expr(edge.expression))

        if lin is None:
            # Havoc: forget everything known about var.
            kept = [c for c in state.constraints
                    if all(v != var for v, _ in (c[1] if c[0] in ("le", "eq", "mod") else ()))]
            return PredicateAbstractState(kept)

        coeffs_e, const_e = lin
        primed = var + "#old"
        eqs, les, mods = [], [], []
        for con in state.constraints:
            kind = con[0]
            if kind == "mod":
                # Rename in modular constraints; projected out below if needed.
                mcoeffs = {(_rename(v, var, primed)): c for v, c in con[1]}
                mods.append(("mod", _coeffs_tuple(mcoeffs), con[2], con[3], con[4]))
            else:
                coeffs = {_rename(v, var, primed): c for v, c in con[1]}
                target = eqs if kind == "eq" else les
                target.append((coeffs, Fraction(con[2])))

        # Add equality: var = sum(coeffs_e * v_old) + const_e
        new_eq = {var: Fraction(1)}
        for v, c in coeffs_e.items():
            rv = _rename(v, var, primed)
            new_eq[rv] = new_eq.get(rv, Fraction(0)) - c
            if new_eq[rv] == 0:
                del new_eq[rv]
        eqs.append((new_eq, const_e))

        # Project out the old value of var.
        if any(primed in c for c, _ in eqs) or any(primed in c for c, _ in les):
            eqs, les = eliminate_variable(eqs, les, primed)
            mods = [m for m in mods if all(v != primed for v, _ in m[1])]

        constraints = []
        for coeffs, rhs in eqs:
            constraints.append(("eq", _coeffs_tuple(coeffs), rhs))
        for coeffs, rhs in les:
            constraints.append(("le", _coeffs_tuple(coeffs), rhs))
        constraints.extend(mods)
        return PredicateAbstractState(constraints)


def _rename(v, var, primed):
    return primed if v == var else v


class PredicateStopOperator(StopOperator):
    """Stop iff some reached state logically implies this state
    (this state is covered by an existing, more general one)."""

    def stop(self, state, reached, precision) -> bool:
        return any(state.is_less_or_equal(r) for r in reached)


class PredicateCPA(ConfigurableProgramAnalysis):
    def __init__(self):
        self._domain = PredicateDomain()
        self._transfer = PredicateTransferRelation()
        self._merge = SepMergeOperator()
        self._stop = PredicateStopOperator()

    def get_abstract_domain(self):
        return self._domain

    def get_transfer_relation(self):
        return self._transfer

    def get_merge_operator(self):
        return self._merge

    def get_stop_operator(self):
        return self._stop

    def get_initial_state(self, node_id: int):
        return PredicateAbstractState()  # no predicates: unconstrained

    def get_initial_precision(self):
        return None


# ---------------------------------------------------------------------------
# Entry point
# ---------------------------------------------------------------------------

def run_predicate_analysis(cfa: CFA, timelimit: float = 900.0) -> VerificationResult:
    """Run predicate analysis on the given CFA."""
    cpa = CompositeCPA([LocationCPA(), PredicateCPA()])
    verdict, stats, error_path = run_cpa_algorithm(cpa, cfa, timelimit)

    result = VerificationResult(verdict=verdict, statistics=stats)
    if verdict == Verdict.FALSE:
        result.property_violated = "assertion"
        result.error_path = error_path
        result.statistics["counterexample"] = _format_path(error_path)
    return result


def _format_path(path: list) -> str:
    parts = []
    for step in path:
        desc = f"L{step['location']}"
        if "edge" in step:
            desc += f" [{step['edge']}]"
        parts.append(desc)
    return " -> ".join(parts)

